\documentclass[border=5pt]{standalone}
\usepackage{tikz}
\usepackage{tikz-3dplot}
\usepackage{pgfplots}
\usepackage{amsmath}
\usepackage{amssymb}
\usepackage{mathrsfs}
\usepackage{cancel}
\usepackage{ifthen}
\usepackage[T1]{fontenc}
\usepackage{array}
\usepackage{colortbl}
\usepackage{makecell}
\usepackage{tkz-euclide}
\usetkzobj{all}
\usetikzlibrary{
  arrows, arrows.meta, calc, intersections, positioning, backgrounds, fit,
  shapes, shapes.geometric, shapes.misc, patterns, angles, quotes, math,
  3d, through, fadings, matrix, trees,
  decorations.markings, decorations.pathmorphing,
  decorations.pathreplacing, decorations.text
}
\usepgfplotslibrary{fillbetween, statistics, colormaps, patchplots}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902,0.624,0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271,0.608,0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{document}
\pagestyle{empty}
\begin{tikzpicture}

% INPUT VALUES ===========
\def\lb{36}   % left benchmark (perfect square)
\def\rb{49}   % right benchmark (perfect square)
\def\dv{45}   % value between benchmarks

% position of 45 on a 0--10 scale
\pgfmathsetmacro{\px}{10*(\dv-\lb)/(\rb-\lb)}

% Axis ===========
\draw[black, line width=0.5mm, <->, >=stealth] (-1,0) -- (11,0);

% Ticks
\draw[thick] (0,0.125) -- (0,-0.125);
\draw[thick] (10,0.125) -- (10,-0.125);
\draw[thick] (\px,0.125) -- (\px,-0.125);

% Dots
\node[circle, draw=none, fill=black, inner sep=3pt] at (0,0) {};
\node[circle, draw=none, fill=black, inner sep=3pt] at (10,0) {};
\node[circle, draw=none, fill=deepskyblue, inner sep=3pt] at (\px,0) {};

% Top scale: values (perfect squares and 45)
\node[above=6pt] at (0,0) {$36$};
\node[above=6pt, deepskyblue] at (\px,0) {$45$};
\node[above=6pt] at (10,0) {$49$};

% Bottom scale: square roots
\node[below=6pt] at (0,0) {$6$};
\node[below=6pt, deepskyblue] at (\px,0) {$\sqrt{45}$};
\node[below=6pt] at (10,0) {$7$};

\end{tikzpicture}
\end{document}
